const canvas = document.getElementById('gameCanvas');
if (!canvas) {
    console.error('No se encontró el elemento #gameCanvas');
    return;
}
const ctx = canvas.getContext('2d');
if (!ctx) {
    console.error('Tu navegador no soporta canvas 2D');
    return;
}

const scoreEl = document.getElementById('score');
const bestEl = document.getElementById('best');
const levelEl = document.getElementById('level');
const overlay = document.getElementById('overlay');
const overlayTitle = document.getElementById('overlayTitle');
const overlayMsg = document.getElementById('overlayMsg');
const restartBtn = document.getElementById('restartBtn');

const gridSize = 20;
const tileCount = 20;
const BASE_STEP_MS = 110;

let snake, food, goldFood, dir, nextDir, score, best, level, running, paused, lastStep, rafId, particles;

// Muros del nivel personalizado (desde el editor de niveles)
let walls = [];
let customLevelName = null;
(function loadCustomLevel() {
    const sel = localStorage.getItem('snake_selected_level');
    if (!sel || sel === 'classic') return;
    const raw = localStorage.getItem('snake_custom_level_' + sel);
    if (!raw) return;
    try {
        walls = JSON.parse(raw).map(function (c) { return { x: c[0], y: c[1] }; });
        customLevelName = sel;
    } catch (e) { walls = []; }
})();

function isWall(x, y) {
    return walls.some(function (w) { return w.x === x && w.y === y; });
}

best = parseInt(localStorage.getItem('snake_best') || '0', 10) || 0;

function init() {
    canvas.width = tileCount * gridSize;
    canvas.height = tileCount * gridSize;
    // si hay muros sobre la posición inicial de la serpiente, los quitamos
    walls = walls.filter(function (w) {
        return !(w.y === 10 && w.x >= 8 && w.x <= 12);
    });
    snake = [{ x: 10, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    level = 1;
    running = true;
    paused = false;
    lastStep = 0;
    particles = [];
    placeFood();
    goldFood = null;
    hideOverlay();
    updateHud();
    cancelAnimationFrame(rafId);
    rafId = requestAnimationFrame(loop);
}

function stepInterval() {
    return Math.max(50, BASE_STEP_MS - (level - 1) * 8);
}

function loop(ts) {
    if (!running) return;
    rafId = requestAnimationFrame(loop);
    if (paused) { draw(); return; }
    if (!lastStep) lastStep = ts;
    if (ts - lastStep >= stepInterval()) {
        tick();
        lastStep = ts;
    }
    updateParticles();
    draw();
}

function tick() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount) {
        gameOver();
        return;
    }
    if (isWall(head.x, head.y)) {
        gameOver();
        return;
    }
    for (let i = 0; i < snake.length; i++) {
        if (snake[i].x === head.x && snake[i].y === head.y) {
            gameOver();
            return;
        }
    }

    snake.unshift(head);

    if (goldFood && head.x === goldFood.x && head.y === goldFood.y) {
        score += 50;
        spawnParticles(goldFood.x, goldFood.y, '#ffd166');
        if (window.SnakeSound) SnakeSound.gold();
        goldFood = null;
        checkLevel();
    } else if (head.x === food.x && head.y === food.y) {
        score += 10;
        spawnParticles(food.x, food.y, '#ff4444');
        if (window.SnakeSound) SnakeSound.eat();
        placeFood();
        checkLevel();
        if (score % 100 === 0 && !goldFood && Math.random() < 0.5) {
            placeGoldFood();
        }
    } else {
        snake.pop();
    }

    updateHud();
}

function checkLevel() {
    const newLevel = Math.floor(score / 50) + 1;
    if (newLevel > level) {
        level = newLevel;
        if (window.SnakeSound) SnakeSound.levelUp();
    }
}

function draw() {
    ctx.fillStyle = '#0f0f1a';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= tileCount; i++) {
        ctx.beginPath();
        ctx.moveTo(i * gridSize, 0);
        ctx.lineTo(i * gridSize, canvas.height);
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(0, i * gridSize);
        ctx.lineTo(canvas.width, i * gridSize);
        ctx.stroke();
    }

    // muros del nivel personalizado
    if (walls.length) {
        ctx.fillStyle = '#8a8aa8';
        for (const w of walls) {
            ctx.fillRect(w.x * gridSize + 1, w.y * gridSize + 1, gridSize - 2, gridSize - 2);
        }
    }

    if (food) {
        ctx.fillStyle = '#ff4444';
        roundRect(food.x * gridSize + 2, food.y * gridSize + 2, gridSize - 4, gridSize - 4, 4);
        ctx.fill();
    }
    if (goldFood) {
        ctx.fillStyle = '#ffd166';
        ctx.shadowColor = '#ffd166';
        ctx.shadowBlur = 8;
        roundRect(goldFood.x * gridSize + 2, goldFood.y * gridSize + 2, gridSize - 4, gridSize - 4, 4);
        ctx.fill();
        ctx.shadowBlur = 0;
    }

    for (let i = 0; i < snake.length; i++) {
        const s = snake[i];
        ctx.fillStyle = i === 0 ? '#7CFF6B' : '#00cc66';
        roundRect(s.x * gridSize + 1, s.y * gridSize + 1, gridSize - 2, gridSize - 2, 5);
        ctx.fill();
    }

    drawParticles();

    if (paused) {
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 28px Segoe UI, Arial';
        ctx.textAlign = 'center';
        ctx.fillText('⏸ Pausa', canvas.width / 2, canvas.height / 2);
        ctx.textAlign = 'left';
    }
}

function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
}

function placeFood() {
    let attempts = 0;
    do {
        food = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };
        attempts++;
    } while ((snake.some(s => s.x === food.x && s.y === food.y) || isWall(food.x, food.y)) && attempts < 200);
}

function placeGoldFood() {
    let attempts = 0;
    do {
        goldFood = { x: Math.floor(Math.random() * tileCount), y: Math.floor(Math.random() * tileCount) };
        attempts++;
    } while ((snake.some(s => s.x === goldFood.x && s.y === goldFood.y) ||
             (food && goldFood.x === food.x && goldFood.y === food.y) ||
             isWall(goldFood.x, goldFood.y)) && attempts < 200);
}

function spawnParticles(gx, gy, color) {
    const cx = gx * gridSize + gridSize / 2;
    const cy = gy * gridSize + gridSize / 2;
    for (let i = 0; i < 8; i++) {
        particles.push({
            x: cx, y: cy,
            vx: (Math.random() - 0.5) * 4,
            vy: (Math.random() - 0.5) * 4,
            life: 1.0,
            color: color,
        });
    }
}

function updateParticles() {
    for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life -= 0.05;
        if (p.life <= 0) particles.splice(i, 1);
    }
}

function drawParticles() {
    for (const p of particles) {
        ctx.globalAlpha = p.life;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x - 2, p.y - 2, 4, 4);
    }
    ctx.globalAlpha = 1;
}

